                        committed.update(tmain)
                        tmain = None
                else:
                    if tother is not None:
                        committed.update(tother)
                        tother = None
            elif op == "rollback":
                if conn == "main":
                    tmain = None
                else:
                    tother = None
            elif op == "put":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                # effective view: committed overlaid with this connection's buffer
                if buf is not None:
                    exists = key in buf or key in committed
                else:
                    exists = key in committed
                changed = 0
                if put_mode == "ignore":
                    if not exists:
                        if buf is not None:
                            buf[key] = val
                        else:
                            committed[key] = val
                        changed = 1
                elif put_mode == "replace":
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    changed = 1
                else:  # upsert
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    changed = 1
                if changed:
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
                    if trig == "after_insert" and not exists:
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
            elif op == "update":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    exists = key in buf or key in committed
                else:
                    exists = key in committed
                if exists:
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
            elif op == "delete":
                key = act.get("key")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    exists = key in buf or key in committed
                else:
                    exists = key in committed
                if exists:
                    if buf is not None:
                        if key in buf:
                            del buf[key]
                        else:
                            # delete from committed inside txn: need tombstone
                            # simplify: mark as deleted in buffer
                            buf[key] = None
                    else:
                        del committed[key]
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
        # final committed state: apply buffers? No, uncommitted not visible.
        # committed dict already has committed changes.
        # But tombstones in buffer not applied. For committed state, ignore buffers.
        # However, committed dict may have been modified directly for non-txn.
        # For txn, committed dict only updated on commit.
        # But we used committed dict for non-txn writes directly. Good.
        # For txn deletes, we set buf[key]=None, not committed. Good.
        # But for txn puts, we set buf[key]=val, not committed. Good.
        # So committed dict is correct committed state.
        # However, for non-txn writes, we modified committed directly. Good.
        # But for txn writes, we need to ensure committed not modified. Good.
        # One issue: for txn put, exists check uses committed, but if key was
