        # If buf[key]=None, key in buf is True, so exists True. That's wrong for
        # delete then put. But rare. Let's handle: if buf has None, treat as not exists.
        # We'll refine later.
        if chan == "changes":
            return changes_main
        elif chan == "total_main":
            return total_main
        else:
            return total_main + total_other

